record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

if picking:
    feedback = (
        'Picking %s chưa đủ hàng để reservation. '
        'Vui lòng bổ sung tồn kho tại location nguồn và kiểm tra khả dụng lại.'
    ) % picking.name

    picking.message_post_with_source(
        'mail.message_activity_done',
        render_values={
            'activity': record,
            'feedback': feedback,
            'display_assignee': record.user_id != env.user,
        },
        mail_activity_type_id=record.activity_type_id.id,
        subtype_xmlid='mail.mt_activities',
    )

picking = env['stock.picking'].browse(record.res_id).exists()

if picking and picking.state not in ('done', 'cancel'):
    picking.action_assign()

    if picking.state != 'assigned':
        if picking.filtered_domain(
            env.ref(
                'fmcg_business_automation.ir_filter_stock_picking_cancellation_candidates'
            )._get_eval_domain()
        ):
            env.ref(
                'fmcg_business_automation.action_schedule_picking_cancellation_review'
            ).with_context(
                active_model='stock.picking',
                active_id=picking.id,
                active_ids=picking.ids,
            ).run()
        else:
            env.ref(
                'fmcg_business_automation.action_feedback_picking_availability'
            ).with_context(
                active_model='mail.activity',
                active_id=record.id,
                active_ids=[record.id],
            ).run()

            record.write({
                'active': True,
                'feedback': False,
            })
    else:
        picking.activity_schedule(
            activity_type_id=env.ref(
                'fmcg_business_automation.mail_activity_type_validate_assigned_picking'
            ).id,
        )

activity_type = env.ref(
    'fmcg_business_automation.'
    'mail_activity_type_check_picking_availability'
)

for picking in records.filtered(
    lambda picking: picking.state == 'confirmed'
):
    existing_activity = env['mail.activity'].search([
        ('res_model', '=', 'stock.picking'),
        ('res_id', '=', picking.id),
        ('activity_type_id', '=', activity_type.id),
        ('active', '=', True),
    ], limit=1)

    if not existing_activity:
        picking.activity_schedule(
            activity_type_id=activity_type.id,
            summary='Kiểm tra khả dụng của phiếu kho',
            note=(
                'Picking đã xác nhận nhưng chưa đủ hàng để reservation. '
                'Vui lòng kiểm tra tồn kho.'
            ),
            user_id=picking.user_id.id or env.user.id,
        )
